@import '../../utils/radius.css';
@import '../../utils/control-density.css';
@import '../../utils/control-parts.css';
@import '../../utils/shimmer.css';

:host {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  box-sizing: border-box;
  min-width: 0;
  vertical-align: middle;
  --ds-skeleton-base: var(--color-foreground-quaternary);
  --ds-shimmer: var(--color-shimmer-shimmer);
  --ds-skeleton-border: var(--color-border-secondary);
}

.skeleton__shape {
  --ds-shimmer-surface-base: var(--ds-skeleton-base);

  display: block;
  width: 100%;
  height: 100%;
  flex: 0 0 auto;
  background-color: var(--ds-skeleton-base);
  border-radius: var(--dimension-radius-025);
}

/* ── Background context ────────────────────────────────────────────────── */

:host(.skeleton--background-medium) {
  --ds-skeleton-border: var(--color-border-on-medium-background-secondary);
  --ds-skeleton-base: var(--color-foreground-on-medium-background-quaternary);
  --ds-shimmer: var(--color-shimmer-shimmer-on-medium-background);
}

:host(.skeleton--background-bold) {
  --ds-skeleton-border: var(--color-border-on-bold-background-secondary);
  --ds-skeleton-base: var(--color-foreground-on-bold-background-quaternary);
  --ds-shimmer: var(--color-shimmer-shimmer-on-bold-background);
}

:host(.skeleton--background-strong) {
  --ds-skeleton-border: var(--color-border-on-strong-background-secondary);
  --ds-skeleton-base: var(--color-foreground-on-strong-background-quaternary);
  --ds-shimmer: var(--color-shimmer-shimmer-on-strong-background);
}

:host(.skeleton--background-translucent) {
  --ds-skeleton-border: var(--color-translucent-border-secondary);
  --ds-skeleton-base: var(--color-translucent-foreground-quaternary);
  --ds-shimmer: var(--color-translucent-shimmer);
}

:host(.skeleton--background-inverted) {
  --ds-skeleton-border: var(--color-inverted-border-secondary);
  --ds-skeleton-base: var(--color-inverted-foreground-quaternary);
  --ds-shimmer: var(--color-inverted-shimmer);
}

:host(.skeleton--background-media) {
  --ds-skeleton-border: var(--color-media-border-secondary);
  --ds-skeleton-base: var(--color-media-foreground-quaternary);
  --ds-shimmer: var(--color-media-shimmer);
}

:host(.skeleton--background-always-dark) {
  --ds-skeleton-border: var(--color-always-dark-border-secondary);
  --ds-skeleton-base: var(--color-always-dark-foreground-quaternary);
  --ds-shimmer: var(--color-always-dark-shimmer);
}

:host(.skeleton--background-navigation) {
  --ds-skeleton-base: var(--color-navigation-foreground-quaternary);
  --ds-shimmer: var(--color-navigation-shimmer);
}

/* ── Text ──────────────────────────────────────────────────────────────── */

:host(.skeleton--text) {
  width: 100%;
  height: var(--ds-skeleton-canvas-size);
  padding-block: 0;
}

:host(.skeleton--text) .skeleton__shape {
  height: 75%;
}

:host(.skeleton--text-text-display-medium) {
  --ds-skeleton-canvas-size: var(--typography-lineheight-3xl);
}
:host(.skeleton--text-text-display-small) {
  --ds-skeleton-canvas-size: var(--typography-lineheight-2xl);
}
:host(.skeleton--text-text-title-large) {
  --ds-skeleton-canvas-size: var(--typography-lineheight-xl);
}
:host(.skeleton--text-text-title-medium),
:host(.skeleton--text-text-body-large) {
  --ds-skeleton-canvas-size: var(--typography-lineheight-lg);
}
:host(.skeleton--text-text-title-small),
:host(.skeleton--text-text-body-medium) {
  --ds-skeleton-canvas-size: var(--typography-lineheight-md);
}
:host(.skeleton--text-text-body-small) {
  --ds-skeleton-canvas-size: var(--typography-lineheight-sm);
}
:host(.skeleton--text-text-caption) {
  --ds-skeleton-canvas-size: var(--typography-lineheight-xs);
}

/* ── Icon ──────────────────────────────────────────────────────────────── */

:host(.skeleton--icon) {
  flex-shrink: 0;
  width: var(--ds-skeleton-canvas-size);
  height: var(--ds-skeleton-canvas-size);
  padding: 0;
}

:host(.skeleton--icon) .skeleton__shape {
  width: 75%;
  height: 75%;
}

:host(.skeleton--icon.skeleton--rounded) .skeleton__shape {
  border-radius: var(--dimension-radius-half);
}

:host(.skeleton--icon-xs) {
  --ds-skeleton-canvas-size: var(--dimension-iconography-xs);
}
:host(.skeleton--icon-sm) {
  --ds-skeleton-canvas-size: var(--dimension-iconography-sm);
}
:host(.skeleton--icon-md) {
  --ds-skeleton-canvas-size: var(--dimension-iconography-md);
}
:host(.skeleton--icon-lg) {
  --ds-skeleton-canvas-size: var(--dimension-iconography-lg);
}
:host(.skeleton--icon-xl) {
  --ds-skeleton-canvas-size: var(--dimension-iconography-xl);
}
:host(.skeleton--icon-2xl) {
  --ds-skeleton-canvas-size: var(--dimension-iconography-2xl);
}
:host(.skeleton--icon-3xl) {
  --ds-skeleton-canvas-size: var(--dimension-iconography-3xl);
}

/* ── Control ───────────────────────────────────────────────────────────── */

:host(.skeleton--control) {
  width: 100%;
  height: var(--ds-control-height);
}

:host(.skeleton--control) .skeleton__shape {
  border-radius: var(--ds-control-radius, var(--dimension-radius-025));
}

:host(.skeleton--control.skeleton--rounded) .skeleton__shape {
  border-radius: var(--dimension-radius-half);
}

.skeleton__control {
  width: 100%;
  height: 100%;
  min-width: 0;
}

.skeleton__control--icon {
  justify-content: center;
  padding: 0;
}

.skeleton__control-label {
  display: flex;
  flex: 1 1 auto;
  align-items: center;
  overflow: hidden;
}

:host(.skeleton--control-outlined) .skeleton__control {
  box-shadow: inset 0 0 0 var(--dimension-stroke-width-012) var(--ds-skeleton-border);
}

:host(.skeleton--rounded) .skeleton__control {
  border-radius: var(--dimension-radius-half);
}

@media (forced-colors: active) {
  .skeleton__shape {
    background-color: var(--ds-forced-color-disabled);
  }
  :host(.skeleton--control-outlined) .skeleton__control {
    outline: var(--dimension-stroke-width-012) solid var(--ds-forced-color-disabled);
    outline-offset: calc(-1 * var(--dimension-stroke-width-012));
  }
}

/* Projected content supplies its intrinsic size, wrapping and responsive metrics. */
:host(.skeleton--preserve-layout) {
  display: grid;
  width: auto;
  height: auto;
  align-items: stretch;
  justify-content: stretch;
  padding: 0;
}

:host(.skeleton--preserve-layout) .skeleton__source,
:host(.skeleton--preserve-layout) .skeleton__control,
:host(.skeleton--preserve-layout) .skeleton__shape {
  grid-area: 1 / 1;
  min-width: 0;
}

.skeleton__source {
  display: grid;
  visibility: hidden;
}

:host(.skeleton--preserve-layout) .skeleton__shape {
  height: 100%;
  width: 100%;
}

:host(.skeleton--preserve-layout.skeleton--text) .skeleton__shape {
  /* Geometry only: inherited text alpha must not dim the skeleton's own token. */
  mask-image: repeating-linear-gradient(
    to bottom,
    transparent 0,
    transparent calc(var(--ds-skeleton-canvas-size) * 0.125),
    rgb(from currentColor r g b / 1) calc(var(--ds-skeleton-canvas-size) * 0.125),
    rgb(from currentColor r g b / 1) calc(var(--ds-skeleton-canvas-size) * 0.875),
    transparent calc(var(--ds-skeleton-canvas-size) * 0.875),
    transparent var(--ds-skeleton-canvas-size)
  );
}

:host(.skeleton--content-ready) .skeleton__source {
  visibility: inherit;
}

import { Component, Element, Prop, State, Watch, h, Host } from '@stencil/core';
import type { IconSize } from '../Icon/Icon';
import type { TextVariant } from '../Text/text-types';
import { CONTROL_TEXT_VARIANT, type ControlSize } from '../../utils/control-text';
import { observeTableCaptionCompact } from '../../utils/table-caption-compact';

export type SkeletonVariant = 'text' | 'icon' | 'control';
export type SkeletonControlAppearance = 'filled' | 'outlined' | 'borderless';
export type SkeletonControlContent =
  | 'label'
  | 'icon'
  | 'icon-label'
  | 'label-icon'
  | 'icon-label-icon';
export type SkeletonBackground =
  | 'faint'
  | 'medium'
  | 'bold'
  | 'strong'
  | 'translucent'
  | 'inverted'
  | 'media'
  | 'navigation'
  | 'always-dark';

/** @slot - Real text or a control whose footprint is retained with preserveLayout. */
@Component({
  tag: 'ds-skeleton',
  styleUrl: 'Skeleton.css',
  shadow: true,
})
export class Skeleton {
  @Element() el!: HTMLElement;
  @Prop() variant: SkeletonVariant = 'text';
  /** Text metric recipe whose line-height defines the text canvas. */
  @Prop() textVariant: TextVariant = 'text-body-medium';
  /** Iconography token whose square canvas defines the icon canvas. */
  @Prop() iconSize: IconSize = 'md';
  /** Shared control-density size whose height defines the control canvas. */
  @Prop() controlSize: ControlSize = 'md';
  /** Filled controls replace the entire shape; other appearances retain the frame and mask its contents. */
  @Prop() controlAppearance: SkeletonControlAppearance = 'filled';
  /** Content anatomy for outlined and borderless control placeholders. */
  @Prop() controlContent: SkeletonControlContent = 'label';
  /** Follow the owning table or data toolbar's compact icon-only control presentation. */
  @Prop() collapseLabel: boolean = false;
  /** Width of text and control skeleton canvases. Numbers resolve to px. Ignored for icons. */
  @Prop() width: string | number | undefined;
  /** Round icon skeletons into circles and control skeletons into pills. Ignored for text. */
  @Prop() rounded: boolean = false;
  /** Whether to show the shimmer animation. */
  @Prop() shimmer: boolean = true;
  /** Derive geometry from a projected control or text instead of estimating its footprint. */
  @Prop() preserveLayout: boolean = false;
  /** With preserveLayout, reveal the same projected content when loading completes. */
  @Prop() isLoading: boolean = true;
  /** Actual parent surface context. Omit on primary and secondary surfaces. */
  @Prop() background: SkeletonBackground | undefined;

  @State() private captionCompact = false;
  private captionCompactDisconnect: (() => void) | undefined;
  private hasLoaded = false;

  componentDidLoad(): void {
    this.hasLoaded = true;
    this.syncCaptionCompactObserver();
  }

  connectedCallback(): void {
    if (this.hasLoaded) this.syncCaptionCompactObserver();
  }

  disconnectedCallback(): void {
    this.disconnectCaptionCompactObserver();
  }

  private disconnectCaptionCompactObserver(): void {
    this.captionCompactDisconnect?.();
    this.captionCompactDisconnect = undefined;
  }

  @Watch('collapseLabel')
  syncCaptionCompactObserver(): void {
    this.disconnectCaptionCompactObserver();
    if (!this.collapseLabel) {
      this.captionCompact = false;
      return;
    }
    this.captionCompactDisconnect = observeTableCaptionCompact(this.el, compact => {
      this.captionCompact = compact;
    });
  }

  private get widthCss() {
    const v = this.width;
    if (v == null) return undefined;
    return typeof v === 'number' ? `${v}px` : v;
  }

  private renderControl() {
    const iconOnly =
      this.controlContent === 'icon' ||
      (this.collapseLabel && this.captionCompact && this.controlContent.includes('icon'));
    const icon = () => (
      <ds-skeleton
        variant="icon"
        iconSize={this.controlSize}
        background={this.background}
        shimmer={this.shimmer}
      />
    );
    return (
      <span
        class={{
          skeleton__control: true,
          'ds-control-frame': true,
          'skeleton__control--icon': iconOnly,
        }}
      >
        {(iconOnly || this.controlContent.startsWith('icon-')) && icon()}
        {!iconOnly && (
          <span class="skeleton__control-label ds-control-label-box">
            <ds-skeleton
              textVariant={CONTROL_TEXT_VARIANT[this.controlSize]}
              background={this.background}
              shimmer={this.shimmer}
            />
          </span>
        )}
        {!iconOnly && this.controlContent.endsWith('-icon') && icon()}
      </span>
    );
  }

  render() {
    return (
      <Host
        aria-hidden={this.isLoading ? 'true' : undefined}
        class={{
          skeleton: true,
          [`skeleton--${this.variant}`]: true,
          [`skeleton--text-${this.textVariant}`]: this.variant === 'text',
          [`skeleton--icon-${this.iconSize}`]: this.variant === 'icon',
          [`ds-control--${this.controlSize}`]: this.variant === 'control',
          [`skeleton--control-${this.controlAppearance}`]: this.variant === 'control',
          [`skeleton--background-${this.background}`]: !!this.background,
          'skeleton--rounded': this.variant !== 'text' && this.rounded,
          'skeleton--preserve-layout': this.preserveLayout,
          'skeleton--content-ready': this.preserveLayout && !this.isLoading,
        }}
        style={this.variant === 'icon' ? undefined : { width: this.widthCss }}
      >
        {this.preserveLayout && (
          <span class="skeleton__source" inert={this.isLoading}>
            <slot />
          </span>
        )}
        {this.isLoading &&
          (this.variant === 'control' && this.controlAppearance !== 'filled' ? (
            this.renderControl()
          ) : (
            <span
              class={{
                skeleton__shape: true,
                'ds-shimmer-surface': this.shimmer,
              }}
            />
          ))}
      </Host>
    );
  }
}
